query:
let newest = toscalar(mv_drops_5m | summarize max(bin_start));
let w = mv_drops_5m | where bin_start > newest - 1h | where isnotempty(region);
union (w | where region == 'Gauteng' | summarize calls = sum(calls), dropped = sum(dropped) | extend scope = 'Gauteng'),
      (w | summarize calls = sum(calls), dropped = sum(dropped) | extend scope = 'All regions')
| extend drop_pct = round(100.0 * todouble(dropped) / calls, 2)
| project scope, calls, dropped, drop_pct
